/* Constructeur d'allocation — 5 classes */
(function () {
  var svg = document.getElementById("al-bar");
  if (!svg) return;
  var KEYS = ["eq","bd","re","co","ca"];
  var COL  = {eq:"#12294a", bd:"#c19a3e", re:"#2f8f83", co:"#b5652f", ca:"#8a94a6"};
  var MU   = {eq:7.0, bd:3.0, re:5.5, co:3.5, ca:2.0};
  var SG   = {eq:16,  bd:6,   re:12,  co:18,  ca:1};
  // matrice de corrélation illustrative (ordre eq,bd,re,co,ca)
  var RHO = {
    eq:{eq:1,   bd:0.10, re:0.60, co:0.25, ca:0.00},
    bd:{eq:0.10,bd:1,    re:0.20, co:-0.10,ca:0.10},
    re:{eq:0.60,bd:0.20, re:1,    co:0.30, ca:0.00},
    co:{eq:0.25,bd:-0.10,re:0.30, co:1,    ca:0.00},
    ca:{eq:0.00,bd:0.10, re:0.00, co:0.00, ca:1}
  };
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }

  function draw() {
    var raw={}, sum=0;
    KEYS.forEach(function(k){ raw[k]=v("al-"+k); sum+=raw[k]; });
    var w={};
    KEYS.forEach(function(k){ w[k]= sum>0 ? raw[k]/sum : 0; setT("al-"+k+"-o", Math.round((sum>0?raw[k]/sum:0)*100)+"%"); });

    var ret=0; KEYS.forEach(function(k){ ret+=w[k]*MU[k]; });
    var varr=0;
    KEYS.forEach(function(i){ KEYS.forEach(function(j){ varr += w[i]*w[j]*SG[i]*SG[j]*RHO[i][j]; }); });
    if (varr<0) varr=0;
    var vol=Math.sqrt(varr);
    var wavg=0; KEYS.forEach(function(k){ wavg+=w[k]*SG[k]; });
    var gain=wavg-vol;

    setT("al-ret", ret.toFixed(2)+"%");
    setT("al-vol", vol.toFixed(2)+"%");
    setT("al-wavg", wavg.toFixed(2)+"%");
    setT("al-gain", "▼ " + Math.max(0, gain).toFixed(2) + " pt σ");

    // stacked bar
    var W=520,H=52, x=0, g="";
    if (sum<=0){ g='<rect x="0" y="14" width="'+W+'" height="24" fill="var(--surface-2)" stroke="var(--border)"/>'; }
    else {
      KEYS.forEach(function(k){
        var wd=w[k]*W;
        if (wd>0.5){
          g+='<rect x="'+x.toFixed(1)+'" y="14" width="'+wd.toFixed(1)+'" height="24" fill="'+COL[k]+'"/>';
          if (wd>34){ g+='<text x="'+(x+wd/2).toFixed(1)+'" y="30" text-anchor="middle" fill="#fff" font-size="11" font-family="var(--sans)" font-weight="600">'+Math.round(w[k]*100)+'%</text>'; }
        }
        x+=wd;
      });
    }
    svg.innerHTML=g;
  }

  KEYS.forEach(function(k){ var e=document.getElementById("al-"+k); if(e) e.addEventListener("input", draw); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
